parameters.inputSchema:
{
 "type": "object",
 "properties": {
   "new_article_content": {
     "type": "string",
     "description": "Complete markdown-formatted blog article section ready for publication. Ensure each subheading has sufficient linebreaks to be presented as a subheading"
   },
   "article_so_far": {
     "type": "string",
     "description": "Everything previously written, with the new article content as well"
   }
 },
  "required": [
    "new_article_content",
    "article_so_far"
  ],
  "additionalProperties": false
}

parameters.jsCode:
const s = $getWorkflowStaticData('global'); // This is per-execution, not global
// Ensure article_so_far exists for this execution
if (typeof s.article_so_far !== 'string') {
  s.article_so_far = '';
}
// Add new content if it exists
if (typeof $json.output?.new_article_content === 'string') {
  s.article_so_far += $json.output.new_article_content;
}
return {
  new_article_content: $json.output?.new_article_content || null,
  article_so_far: s.article_so_far
};

const s = $getWorkflowStaticData('global'); // persistent article accumulator per execution
// Initialize article content to previous run, or blank if first use
if (typeof s.article_so_far !== 'string') s.article_so_far = '';
// Append new section (always a markdown-formatted string)
if (typeof $json.output.new_article_content === 'string') {
  s.article_so_far += $json.output.new_article_content;
}
// Output the full article (with all appended content so far)
// This can be sent to the start of the next loop iteration, ensuring accumulation.
return {
  new_article_content: $json.output.new_article_content,          // current section as received
  article_so_far: s.article_so_far                        // cumulative markdown string for all sections so far
};

const s = $getWorkflowStaticData('global');
// Clear this execution's data
s.article_so_far = '';
return {};

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "seo_metadata": {
      "type": "object",
      "properties": {
        "title": {
          "type": "string"
        },
        "slug": {
          "type": "string"
        },
        "subheading": {
          "type": "string"
        },
        "excerpt": {
          "type": "string"
        },
        "category": {
          "type": "string"
        },
        "tags": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "cover_image": {
          "type": "object",
          "properties": {
            "url": {
              "type": "string"
            },
            "alt_text": {
              "type": "string"
            }
          }
        }
      }
    },
    "completed_article": {
